draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bird
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 + 50 * Math.sin(t), H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H/2);
  ctx.lineTo(W/2 + 50 * Math.sin(t) + 20 * Math.cos(t), H/2 + 20 * Math.sin(t));
  ctx.stroke();

  // fish
  ctx.beginPath();
  ctx.arc(W/2 - 100, H - 50 + 20 * Math.sin(t), 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H - 50 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 100 + 10 * Math.cos(t), H - 50 + 20 * Math.sin(t) + 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
